            : t("emailTemplates.createTitle")}
        </h1>
        <p className="mt-1 text-sm text-zinc-400">
          {templateId
            ? t("emailTemplates.editSubtitle")
            : t("emailTemplates.createSubtitle")}
        </p>
      </div>

