"use client";

import Image from "next/image";

interface CatalogCardProps {
  id: string;
  name: string;
  selected: boolean;
  preview?: { status: string; url: string | null } | null;
  onSelect: (id: string) => void;
}

export function CatalogCard({ id, name, selected, preview, onSelect }: CatalogCardProps) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      onClick={() => onSelect(id)}
      className={`overflow-hidden rounded-xl border text-left transition ${
        selected
          ? "border-brand-blue ring-2 ring-brand-blue/30"
          : "border-white/10 hover:border-brand-blue/50"
      }`}
    >
      <div className="relative h-36 w-full bg-white/5">
        {preview?.status === "READY" && preview.url ? (
          <Image
            src={preview.url}
            alt={`Preview of ${name}`}
            fill
            unoptimized
            className="object-cover object-top"
          />
        ) : (
          <div className="flex h-full items-center justify-center text-zinc-500">
            <i className="pi pi-image text-3xl" aria-hidden="true" />
            <span className="sr-only">Preview unavailable</span>
          </div>
        )}
      </div>
      <div className="flex items-center justify-between gap-2 p-3">
        <span className="truncate text-sm font-medium text-white">{name}</span>
        {selected ? <i className="pi pi-check-circle text-brand-cyan" aria-hidden="true" /> : null}
      </div>
    </button>
  );
}

"use client";

import { ErrorMessage, Field, Form, useFormikContext } from "formik";
import { Button } from "primereact/button";
import { Dropdown } from "primereact/dropdown";
import { InputText } from "primereact/inputtext";
import { InputNumber } from "primereact/inputnumber";
import { InputSwitch } from "primereact/inputswitch";
import type { CampaignFormValues, EmailTemplateListItemView, PageListItemView } from "@next-phish/shared";
import { CatalogCard } from "@/src/components/molecules/catalog-card";
import { FormMessage } from "@/src/components/atoms/form-message";

interface Props {
  emailTemplates: EmailTemplateListItemView[];
  pages: PageListItemView[];
  sendingProfiles: Array<{ id: string; name: string }>;
  targetGroups: Array<{ id: string; name: string; usersCount?: number }>;
  error: string;
  onCancel: () => void;
}

const fieldClass = "w-full rounded-xl border border-white/10 bg-white/95 text-slate-900";

export function CampaignFormPresentation({ emailTemplates, pages, sendingProfiles, targetGroups, error, onCancel }: Props) {
  const { values, setFieldValue, isSubmitting } = useFormikContext<CampaignFormValues>();
  return (
    <Form className="space-y-7">
      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Name</span>
          <Field as={InputText} name="name" className={fieldClass} />
          <ErrorMessage name="name" component="p" className="text-sm text-red-400" />
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Campaign type</span>
          <Field as={Dropdown} name="type" options={[{ label: "Template", value: "TEMPLATE" }, { label: "Concrete campaign", value: "CONCRETE" }]} className={fieldClass} />
        </label>
      </div>

      <section>
        <h2 className="mb-3 text-lg font-semibold text-white">Email template</h2>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {emailTemplates.map((item) => <CatalogCard key={item.id} {...item} selected={values.emailTemplateId === item.id} onSelect={(id) => setFieldValue("emailTemplateId", id)} />)}
        </div>
        <ErrorMessage name="emailTemplateId" component="p" className="mt-2 text-sm text-red-400" />
      </section>

      <section>
        <h2 className="mb-3 text-lg font-semibold text-white">Landing page</h2>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {pages.map((item) => <CatalogCard key={item.id} {...item} selected={values.pageId === item.id} onSelect={(id) => setFieldValue("pageId", id)} />)}
        </div>
        <ErrorMessage name="pageId" component="p" className="mt-2 text-sm text-red-400" />
      </section>

      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Sending profile</span>
          <Field as={Dropdown} name="mailSendingProfileId" options={sendingProfiles} optionLabel="name" optionValue="id" placeholder="Select a profile" className={fieldClass} />
          <ErrorMessage name="mailSendingProfileId" component="p" className="text-sm text-red-400" />
        </label>
        {values.type === "CONCRETE" ? (
          <label className="space-y-2 text-sm text-zinc-300">
            <span>Target group</span>
            <Field as={Dropdown} name="targetGroupId" options={targetGroups} optionLabel="name" optionValue="id" placeholder="Select a group" className={fieldClass} />
            <ErrorMessage name="targetGroupId" component="p" className="text-sm text-red-400" />
          </label>
        ) : null}
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Target timezone</span>
          <Field as={InputText} name="targetTimezone" className={fieldClass} placeholder="Europe/London" />
          <ErrorMessage name="targetTimezone" component="p" className="text-sm text-red-400" />
        </label>
      </div>

      <div className="rounded-xl border border-white/10 p-4">
        <div className="flex items-center justify-between">
          <div><p className="font-medium text-white">Automatically complete campaign</p><p className="text-sm text-zinc-400">Defaults to 20 days after start.</p></div>
          <InputSwitch checked={values.automaticallyComplete} onChange={(event) => { void setFieldValue("automaticallyComplete", event.value); if (!event.value) void setFieldValue("autoCompleteAfterDays", null); }} />
        </div>
        {values.automaticallyComplete ? <div className="mt-4 max-w-xs"><InputNumber value={values.autoCompleteAfterDays} min={1} onValueChange={(event) => void setFieldValue("autoCompleteAfterDays", event.value ?? null)} suffix=" days" className="w-full" /></div> : null}
      </div>

      {error ? <FormMessage variant="error">{error}</FormMessage> : null}
      <div className="flex justify-end gap-3">
        <Button type="button" outlined label="Cancel" onClick={onCancel} />
        <Button type="submit" label="Save campaign" loading={isSubmitting} className="border-0 bg-brand-blue" />
      </div>
    </Form>
  );
}

"use client";

import { Formik } from "formik";
import { useRouter } from "next/navigation";
import { campaignFormSchema, type CampaignFormValues } from "@next-phish/shared";
import { FormSkeleton } from "@/src/components/atoms/form-skeleton";
import { useCampaignAuthoring } from "@/src/hooks/use-campaign-authoring";
import { useFormStatus } from "@/src/hooks/use-form-status";
import { toFormikValidation } from "@/src/lib/to-formik-validation";
import { CampaignFormPresentation } from "./form-presentation";

export function CampaignFormContainer({ campaignId }: { campaignId?: string }) {
  const router = useRouter();
  const { status, setError, reset } = useFormStatus();
  const { campaign, isLoading, create, update, ...catalogs } = useCampaignAuthoring(campaignId);
  if (isLoading) return <FormSkeleton />;
  if (campaignId && !campaign.data) return <p className="p-8 text-zinc-400">Campaign not found.</p>;

  const row = campaign.data;
  const initialValues: CampaignFormValues = {
    name: row?.name ?? "",
    type: row?.type ?? "CONCRETE",
    emailTemplateId: row?.emailTemplateId ?? "",
    pageId: row?.pageId ?? "",
    mailSendingProfileId: row?.mailSendingProfileId ?? "",
    targetGroupId: row?.targetGroupId ?? null,
    targetTimezone: row?.targetTimezone ?? Intl.DateTimeFormat().resolvedOptions().timeZone,
    automaticallyComplete: row?.autoCompleteAfterDays !== null,
    autoCompleteAfterDays: row?.autoCompleteAfterDays ?? 20,
  };

  async function submit(values: CampaignFormValues) {
    reset();
    const payload = {
      name: values.name,
      type: values.type,
      emailTemplateId: values.emailTemplateId,
      pageId: values.pageId,
      mailSendingProfileId: values.mailSendingProfileId,
      targetGroupId: values.type === "TEMPLATE" ? null : values.targetGroupId,
      targetTimezone: values.targetTimezone,
      autoCompleteAfterDays: values.automaticallyComplete ? values.autoCompleteAfterDays : null,
    };
    try {
      const saved = campaignId
        ? await update.mutateAsync({ id: campaignId, data: payload })
        : await create.mutateAsync(payload);
      router.push(`/campaigns/${saved.id}`);
    } catch (error) {
      setError(error instanceof Error ? error.message : "Campaign could not be saved");
    }
  }

  return (
    <div className="px-6 py-8">
      <h1 className="text-2xl font-semibold text-white">{campaignId ? "Edit campaign" : "Create campaign"}</h1>
      <p className="mb-7 mt-1 text-sm text-zinc-400">Choose reusable organization assets and campaign behavior.</p>
      <Formik initialValues={initialValues} enableReinitialize validate={toFormikValidation(campaignFormSchema)} onSubmit={submit}>
        <CampaignFormPresentation {...catalogs} error={status.type === "error" ? status.message : ""} onCancel={() => router.push("/campaigns")} />
      </Formik>
    </div>
  );
}

