"use client";

import { useParams, useRouter } from "next/navigation";
import { Button } from "primereact/button";
import { trpc } from "@/src/lib/trpc";

export default function CampaignDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const utils = trpc.useUtils();
  const { data, isLoading } = trpc.campaign.getById.useQuery({ id });
  const invalidate = () => Promise.all([utils.campaign.getById.invalidate({ id }), utils.campaign.list.invalidate()]);
  const publish = trpc.campaign.publish.useMutation({ onSuccess: invalidate });
  const pause = trpc.campaign.pause.useMutation({ onSuccess: invalidate });
  const resume = trpc.campaign.resume.useMutation({ onSuccess: invalidate });
  const complete = trpc.campaign.complete.useMutation({ onSuccess: invalidate });
  const clone = trpc.campaign.clone.useMutation({ onSuccess: (copy) => router.push(`/campaigns/${copy.id}`) });
  if (isLoading) return <p className="p-8 text-zinc-400">Loading campaign…</p>;
  if (!data) return <p className="p-8 text-zinc-400">Campaign not found.</p>;
  const canEdit = data.status === "DRAFT" || data.status === "PUBLISHED";
  return (
    <div className="px-6 py-8">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div><p className="text-sm text-brand-blue">{data.type === "TEMPLATE" ? "Template" : "Concrete campaign"}</p><h1 className="text-2xl font-semibold text-white">{data.name}</h1><p className="mt-1 text-sm text-zinc-400">{data.status.replaceAll("_", " ")}</p></div>
        <div className="flex flex-wrap gap-2">
          {canEdit ? <Button outlined label="Edit" onClick={() => router.push(`/campaigns/${id}/edit`)} /> : null}
          {data.status === "DRAFT" ? <Button label="Publish" onClick={() => publish.mutate({ id })} /> : null}
          <Button outlined label="Clone" onClick={() => clone.mutate({ id, name: `${data.name} copy`, type: data.type, targetGroupId: data.type === "CONCRETE" ? data.targetGroupId : null })} />
          {data.type === "CONCRETE" && data.status === "PUBLISHED" ? <Button label="Schedule" onClick={() => router.push(`/schedule/new?campaignId=${id}`)} /> : null}
          {["PENDING_START", "ACTIVE"].includes(data.status) ? <Button label="Pause" onClick={() => pause.mutate({ id })} /> : null}
          {data.status === "PAUSED" ? <Button label="Resume" onClick={() => resume.mutate({ id })} /> : null}
          {["ACTIVE", "PAUSED"].includes(data.status) ? <Button severity="danger" outlined label="Complete" onClick={() => complete.mutate({ id })} /> : null}
        </div>
      </div>
      <div className="mt-8 grid gap-4 md:grid-cols-2">
        {[["Email template", data.emailTemplate?.name], ["Landing page", data.page?.name], ["Sending profile", data.mailSendingProfile?.name], ["Target group", data.targetGroup?.name], ["Timezone", data.targetTimezone]].map(([label, value]) => <div key={label} className="rounded-xl border border-white/10 bg-brand-dark p-4"><p className="text-xs uppercase text-zinc-500">{label}</p><p className="mt-1 text-white">{value ?? "Not selected"}</p></div>)}
      </div>
    </div>
  );
}

