"use client";

import { ErrorMessage, Field, Form, useFormikContext } from "formik";
import { Button } from "primereact/button";
import { Dropdown } from "primereact/dropdown";
import { InputText } from "primereact/inputtext";
import { InputNumber } from "primereact/inputnumber";
import { MultiSelect } from "primereact/multiselect";
import { Checkbox } from "primereact/checkbox";
import type { ScheduleFormValues } from "@next-phish/shared";
import { FormMessage } from "@/src/components/atoms/form-message";

interface Props {
  campaigns: Array<{ id: string; name: string; type: "TEMPLATE" | "CONCRETE" }>;
  targetGroups: Array<{ id: string; name: string; userCount: number }>;
  error: string;
  onCancel: () => void;
}
const fieldClass = "w-full rounded-xl border border-white/10 bg-white/95 text-slate-900";

export function ScheduleFormPresentation({ campaigns, targetGroups, error, onCancel }: Props) {
  const { values, setFieldValue, isSubmitting } = useFormikContext<ScheduleFormValues>();
  const selectedGroup = targetGroups.find((group) => group.id === values.targetGroupId);
  const repeatingSources = campaigns.filter((campaign) => campaign.type === "TEMPLATE");
  return (
    <Form className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300"><span>Name</span><Field as={InputText} name="name" className={fieldClass} /><ErrorMessage name="name" component="p" className="text-red-400" /></label>
        <label className="space-y-2 text-sm text-zinc-300"><span>Schedule type</span><Dropdown value={values.type} options={[{ label: "One time", value: "ONE_TIME" }, { label: "Repeating", value: "RECURRING" }]} onChange={(event) => { void setFieldValue("type", event.value); void setFieldValue("sourceCampaignIds", []); }} className={fieldClass} /></label>
        <label className="space-y-2 text-sm text-zinc-300 md:col-span-2"><span>Campaign source</span>{values.type === "RECURRING" ? <MultiSelect value={values.sourceCampaignIds} options={repeatingSources} optionLabel="name" optionValue="id" onChange={(event) => void setFieldValue("sourceCampaignIds", event.value)} className={fieldClass} display="chip" /> : <Dropdown value={values.sourceCampaignIds[0] ?? null} options={campaigns} optionLabel="name" optionValue="id" onChange={(event) => void setFieldValue("sourceCampaignIds", [event.value])} className={fieldClass} />}</label>
        <label className="space-y-2 text-sm text-zinc-300"><span>Target group</span><Dropdown value={values.targetGroupId} options={targetGroups} optionLabel="name" optionValue="id" onChange={(event) => { void setFieldValue("targetGroupId", event.value); const group = targetGroups.find((item) => item.id === event.value); if (group && group.userCount > 600) { void setFieldValue("deliveryMode", "DRIP"); void setFieldValue("dripEmailsPerMinute", 60); void setFieldValue("batchSize", null); void setFieldValue("batchIntervalMinutes", null); } }} placeholder="Inherited for a concrete source" className={fieldClass} showClear /></label>
        <label className="space-y-2 text-sm text-zinc-300"><span>Target timezone</span><Field as={InputText} name="targetTimezone" className={fieldClass} /></label>
        <label className="space-y-2 text-sm text-zinc-300"><span>First occurrence</span><Field as={InputText} type="datetime-local" name="startsAt" className={fieldClass} /></label>
      </div>
      {selectedGroup && selectedGroup.userCount > 600 ? <FormMessage variant="success">For {selectedGroup.userCount} recipients, Drip at 60 emails/minute is recommended and remains configurable.</FormMessage> : null}

      {values.type === "RECURRING" ? <section className="grid gap-4 rounded-xl border border-white/10 p-4 md:grid-cols-3">
        <label className="space-y-2 text-sm text-zinc-300"><span>Frequency</span><Dropdown value={values.frequency} options={["WEEKLY", "MONTHLY", "QUARTERLY", "HALF_YEARLY", "YEARLY"].map((value) => ({ label: value.replaceAll("_", " "), value }))} onChange={(event) => void setFieldValue("frequency", event.value)} className={fieldClass} /></label>
        <label className="space-y-2 text-sm text-zinc-300"><span>Strategy</span><Dropdown value={values.selectionStrategy} options={[{ label: "Deck", value: "DECK" }, { label: "Random", value: "RANDOM" }]} onChange={(event) => void setFieldValue("selectionStrategy", event.value)} className={fieldClass} /></label>
        <label className="space-y-2 text-sm text-zinc-300"><span>Local time (minutes after midnight)</span><InputNumber value={values.localTimeMinutes} min={0} max={1439} onValueChange={(event) => void setFieldValue("localTimeMinutes", event.value ?? null)} className="w-full" /></label>
        {values.frequency === "WEEKLY" ? <label className="space-y-2 text-sm text-zinc-300"><span>Weekday</span><InputNumber value={values.weekday} min={0} max={6} onValueChange={(event) => void setFieldValue("weekday", event.value ?? null)} className="w-full" /></label> : null}
        {values.frequency && values.frequency !== "WEEKLY" ? <label className="space-y-2 text-sm text-zinc-300"><span>Day of month</span><InputNumber value={values.dayOfMonth} min={1} max={31} onValueChange={(event) => void setFieldValue("dayOfMonth", event.value ?? null)} className="w-full" /></label> : null}
        {["QUARTERLY", "HALF_YEARLY", "YEARLY"].includes(values.frequency ?? "") ? <label className="space-y-2 text-sm text-zinc-300"><span>Month in period</span><InputNumber value={values.month} min={1} max={values.frequency === "QUARTERLY" ? 3 : values.frequency === "HALF_YEARLY" ? 6 : 12} onValueChange={(event) => void setFieldValue("month", event.value ?? null)} className="w-full" /></label> : null}
        {values.selectionStrategy === "DECK" ? <label className="flex items-center gap-2 text-sm text-zinc-300"><Checkbox checked={values.shuffleDeck} onChange={(event) => void setFieldValue("shuffleDeck", Boolean(event.checked))} /> Shuffle before first occurrence</label> : null}
      </section> : null}

      <section className="grid gap-4 rounded-xl border border-white/10 p-4 md:grid-cols-3">
        <label className="space-y-2 text-sm text-zinc-300"><span>Delivery mode</span><Dropdown value={values.deliveryMode} options={["BLAST", "DRIP", "BATCH"].map((value) => ({ label: value, value }))} onChange={(event) => { void setFieldValue("deliveryMode", event.value); void setFieldValue("dripEmailsPerMinute", event.value === "DRIP" ? (values.dripEmailsPerMinute ?? 60) : null); void setFieldValue("batchSize", event.value === "BATCH" ? (values.batchSize ?? 100) : null); void setFieldValue("batchIntervalMinutes", event.value === "BATCH" ? (values.batchIntervalMinutes ?? 60) : null); }} className={fieldClass} /></label>
        {values.deliveryMode === "DRIP" ? <label className="space-y-2 text-sm text-zinc-300"><span>Emails per minute</span><InputNumber value={values.dripEmailsPerMinute} min={1} onValueChange={(event) => void setFieldValue("dripEmailsPerMinute", event.value ?? null)} className="w-full" /></label> : null}
        {values.deliveryMode === "BATCH" ? <><label className="space-y-2 text-sm text-zinc-300"><span>Batch size</span><InputNumber value={values.batchSize} min={1} onValueChange={(event) => void setFieldValue("batchSize", event.value ?? null)} className="w-full" /></label><label className="space-y-2 text-sm text-zinc-300"><span>Interval (minutes)</span><InputNumber value={values.batchIntervalMinutes} min={1} onValueChange={(event) => void setFieldValue("batchIntervalMinutes", event.value ?? null)} className="w-full" /></label></> : null}
      </section>
      {error ? <FormMessage variant="error">{error}</FormMessage> : null}
      <div className="flex justify-end gap-3"><Button type="button" outlined label="Cancel" onClick={onCancel} /><Button type="submit" label="Save schedule" loading={isSubmitting} className="border-0 bg-brand-blue" /></div>
    </Form>
  );
}

"use client";

import { Formik } from "formik";
import { useRouter } from "next/navigation";
import { scheduleFormSchema, type ScheduleFormValues } from "@next-phish/shared";
import { trpc } from "@/src/lib/trpc";
import { useFormStatus } from "@/src/hooks/use-form-status";
import { toFormikValidation } from "@/src/lib/to-formik-validation";
import { ScheduleFormPresentation } from "./form-presentation";

export function ScheduleFormContainer({ campaignId }: { campaignId?: string }) {
  const router = useRouter();
  const { status, setError, reset } = useFormStatus();
  const campaigns = trpc.campaign.list.useQuery({ status: "PUBLISHED", limit: 100, offset: 0 });
  const groups = trpc.targetGroup.list.useQuery({ limit: 100, offset: 0, filters: { status: "ACTIVE" } });
  const create = trpc.campaign.createSchedule.useMutation();
  const initialValues: ScheduleFormValues = {
    name: "",
    type: "ONE_TIME",
    sourceCampaignIds: campaignId ? [campaignId] : [],
    targetGroupId: null,
    targetTimezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    startsAt: "",
    frequency: null,
    localTimeMinutes: null,
    weekday: null,
    dayOfMonth: null,
    month: null,
    selectionStrategy: null,
    shuffleDeck: false,
    deliveryMode: "BLAST",
    dripEmailsPerMinute: null,
    batchSize: null,
    batchIntervalMinutes: null,
    maxCampaigns: null,
    endsAt: null,
    autoCompleteAfterDays: 20,
  };
  async function submit(values: ScheduleFormValues) {
    reset();
    try {
      const recurring = values.type === "RECURRING";
      const result = await create.mutateAsync({
        ...values,
        startsAt: new Date(values.startsAt),
        endsAt: values.endsAt ? new Date(values.endsAt) : null,
        frequency: recurring ? values.frequency : null,
        selectionStrategy: recurring ? values.selectionStrategy : null,
        localTimeMinutes: recurring ? values.localTimeMinutes : null,
        weekday: recurring ? values.weekday : null,
        dayOfMonth: recurring ? values.dayOfMonth : null,
        month: recurring ? values.month : null,
        shuffleDeck: recurring ? values.shuffleDeck : false,
      });
      router.push(`/schedule/${result.schedule.id}`);
    } catch (error) {
      setError(error instanceof Error ? error.message : "Schedule could not be saved");
    }
  }
  return (
    <div className="px-6 py-8">
      <h1 className="text-2xl font-semibold text-white">Create schedule</h1>
      <p className="mb-7 mt-1 text-sm text-zinc-400">Configure timing and delivery. Sending remains deferred.</p>
      <Formik initialValues={initialValues} validate={toFormikValidation(scheduleFormSchema)} onSubmit={submit}>
        <ScheduleFormPresentation campaigns={(campaigns.data?.rows ?? []).map(({ id, name, type }) => ({ id, name, type }))} targetGroups={groups.data?.targetGroups ?? []} error={status.type === "error" ? status.message : ""} onCancel={() => router.push("/schedule")} />
      </Formik>
    </div>
  );
}

