  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const { data, isLoading } = trpc.campaign.getSchedule.useQuery({ id });
  if (isLoading) return <p className="p-8 text-zinc-400">Loading schedule…</p>;
  if (!data) return <p className="p-8 text-zinc-400">Schedule not found.</p>;
  return <div className="px-6 py-8"><div className="flex items-start justify-between gap-4"><div><p className="text-sm text-brand-blue">{data.type.replace("_", " ")}</p><h1 className="text-2xl font-semibold text-white">{data.name}</h1><p className="mt-1 text-zinc-400">{data.status}</p></div><Button outlined label="Back" onClick={() => router.push("/schedule")} /></div><div className="mt-8 grid gap-4 md:grid-cols-2">{[["Starts", new Date(data.startsAt).toLocaleString()], ["Timezone", data.targetTimezone], ["Delivery", data.deliveryMode], ["Target group", data.targetGroup?.name ?? "Inherited"], ["Frequency", data.frequency ?? "One time"], ["Sources", data.sources.map((source) => source.campaign.name).join(", ")]].map(([label, value]) => <div key={label} className="rounded-xl border border-white/10 bg-brand-dark p-4"><p className="text-xs uppercase text-zinc-500">{label}</p><p className="mt-1 text-white">{value}</p></div>)}</div></div>;
}

